package com.vitalpulse.cloudcare.common.util;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.vitalpulse.cloudcare.common.model.AuditLog;

public class AuditLogger {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    public static void log(AuditLog auditLog) {
        try {
            String logString = MAPPER.writeValueAsString(auditLog);
            System.out.println(logString);
        } catch (JsonProcessingException e) {
            System.err.println("Failed to serialize audit log: " + e.getMessage());
        }
    }
}

