MedicationOrder newOrder = orderService.createOrder(orderRequest);

// New Audit Logging logic
try {
    String principalId = request.getRequestContext().getAuthorizer().get("principalId").toString();
    Map<String, Object> details = new HashMap<>();
    details.put("patientId", newOrder.getPatientId());
    details.put("medication", newOrder.getMedication());

    AuditLog auditLog = AuditLog.builder()
        .timestamp(Instant.now().toString())
        .serviceName("order-management-command")
        .principalId(principalId)
        .action("CREATE_ORDER")
        .entityType("MedicationOrder")
        .entityId(newOrder.getOrderId())
        .details(details)
        .build();
    AuditLogger.log(auditLog);
} catch (Exception e) {
    // Log error but do not fail the main request
    System.err.println("Error during audit logging: " + e.getMessage());
}

